mapper.select:
SELECT

FROM InstrumentsCurrency a WHERE 1 = 1

    AND a.instType = #{instType}


    AND a.instId = #{instId}


    AND a.blockchain = #{blockchain}


    AND a.currencyName = #{currencyName}


    AND a.currencyDesc = #{currencyDesc}


    AND a.currencyNum = #{currencyNum}


    AND a.currencyContract = #{currencyContract}


    AND a.currencyPmDesc = #{currencyPmDesc}


    AND a.currencyLink = #{currencyLink}


    AND a.currencySite = #{currencySite}


    AND a.currencyBrowser = #{currencyBrowser}


    AND a.currencyWhitepaperUrl = #{currencyWhitepaperUrl}


    AND a.currencyX = #{currencyX}


    AND a.currencyTelegram = #{currencyTelegram}


    AND a.currencyLogoUrl = #{currencyLogoUrl}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1
